// Lightweight, pluggable cache facade used by the library
// If a user supplies a custom cache object via options.cache, it will be used directly.
// The default cache below provides a simple in-memory TTL cache.

class InMemoryCache {
  constructor() {
    this.store = new Map();
    this.defaultTTL = 60 * 60 * 1000; // 1 hour in ms
  }

  _now() {
    return Date.now();
  }

  get(key) {
    const entry = this.store.get(key);
    if (!entry) return undefined;
    if (entry.expires !== undefined && entry.expires <= this._now()) {
      this.store.delete(key);
      return undefined;
    }
    return entry.value;
  }

  set(key, value, ttl) {
    const expires = this._now() + (ttl ?? this.defaultTTL);
    this.store.set(key, { value, expires });
  }

  del(key) {
    this.store.delete(key);
  }

  close() {
    this.store.clear();
  }
}

function createCache(userCache) {
  // If user supplied a cache-like object with get/set/del, use it directly
  if (userCache && typeof userCache.get === 'function' && typeof userCache.set === 'function') {
    // We expect userCache to implement at least get and set; del/close are optional
    return userCache;
  }
  // Otherwise, fall back to internal in-memory cache
  return new InMemoryCache();
}

module.exports = {
  createCache
};
